const base = $('Prepare Prospect').item.json;
const r = $input.item.json || {};
const d = r.data && !Array.isArray(r.data) ? r.data : {};
const emails = Array.isArray(d.emails) ? d.emails : [];
const best = emails.find((e) => e.smtp_status === 'valid') || emails[0];
const ok = r.status === 'completed' && !!best && !!best.email;
const lastOk = base.last_name && !String(base.last_name).includes('*') ? base.last_name : '';
return { json: {
  ...base,
  first_name: d.first_name || base.first_name,
  last_name: d.last_name || lastOk,
  linkedin_url: d.linkedin_url || '',
  email: ok ? best.email : '',
  email_status: ok ? (best.smtp_status || 'unknown') : 'NOT_FOUND',
  reveal_status: r.status || 'n/a',
} };

const HR_TITLE = /(\bhr\b|human resources|talent|recruit|people|hiring|staffing)/i;
const clean = (s) => String(s || '').toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/\b(pvt|private|ltd|limited|llp|llc|inc|incorporated|corp|corporation|co|company)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const hostOf = (u) => String(u || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
const sameDomain = (a, b) => !!a && !!b && (a === b || a.endsWith('.' + b) || b.endsWith('.' + a));
const sameName = (x, y) => {
  const a = clean(x), b = clean(y);
  if (!a || !b) return false;
  return a === b || (Math.min(a.length, b.length) >= 4 && (a.includes(b) || b.includes(a)));
};
const titleTokens = (t) => new Set(
  String(t || '').toLowerCase()
    .replace(/human resources?/g, 'hr')
    .replace(/recruitment|recruiter|recruiting/g, 'recruit')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(/\s+/)
    .filter((w) => w && !['and', 'of', 'the', 'for', 'a'].includes(w))
);
const titleMatch = (a, b) => {
  const x = titleTokens(a), y = titleTokens(b);
  if (!x.size || !y.size) return false;
  const [small, big] = x.size <= y.size ? [x, y] : [y, x];
  const inter = [...small].filter((w) => big.has(w)).length;
  if (small.size >= 2 && inter === small.size) return true;
  return inter / new Set([...x, ...y]).size >= 0.6;
};

const p = $('Compile Revealed Contact').item.json;
const res = $input.item.json || {};

const rec = Array.isArray(res.data) ? res.data[0] : null;
const result = rec && rec.result;
const hasProfile = !!result && !Array.isArray(result) && typeof result === 'object' && Object.keys(result).length > 0;
const positions = hasProfile && Array.isArray(result.positions) ? result.positions : [];

const out = {
  ...p,
  location: (hasProfile && result.location) || p.location,
  current_positions_count: positions.length,
  current_company_name: '',
  current_company_domain: '',
  current_company_title: '',
  route_to_leads: false,
  old_email: '',
};

if (res.status !== 'completed') {
  return { json: { ...out, employment_status: 'UNCONFIRMED', lead_status: 'REVIEW_LOOKUP_INCOMPLETE',
    verification_reason: 'LinkedIn lookup did not complete (status: ' + (res.status || (res.error && res.error.message) || 'unknown') + '); email not verified' } };
}
if (!hasProfile) {
  return { json: { ...out, employment_status: 'NO_PROFILE_DATA', lead_status: 'REVIEW_NO_PROFILE',
    verification_reason: 'Snov.io returned no LinkedIn profile data; email not verified' } };
}
if (positions.length === 0) {
  return { json: { ...out, employment_status: 'NO_CURRENT_POSITION', lead_status: 'REVIEW_NO_CURRENT_POSITION',
    verification_reason: 'LinkedIn profile lists no current position; email not verified' } };
}

const sameCo = positions.filter((x) =>
  sameDomain(hostOf(x.url), String(p.company_domain || '').toLowerCase()) || sameName(x.name, p.company_name));

if (sameCo.length) {
  const exact = sameCo.find((x) => titleMatch(x.title, p.job_title));
  const m = exact || sameCo.find((x) => HR_TITLE.test(x.title || '')) || sameCo[0];
  const hasEmail = !!p.email;
  if (exact) {
    return { json: { ...out, employment_status: 'VERIFIED',
      lead_status: hasEmail ? 'APPROVED_VERIFIED_CURRENT' : 'REVIEW_NO_EMAIL',
      route_to_leads: hasEmail,
      email_source: 'snov_reveal_verified',
      current_company_name: m.name || p.company_name, current_company_title: m.title || '',
      final_company_name: m.name || p.company_name, final_company_domain: p.company_domain,
      final_job_title: m.title || p.job_title,
      verification_reason: 'Company and designation match LinkedIn (' + (m.name || '') + ' - ' + (m.title || '') + ')' } };
  }
  return { json: { ...out, employment_status: 'VERIFIED_TITLE_CHANGED',
    lead_status: hasEmail ? 'APPROVED_VERIFIED_CURRENT' : 'REVIEW_NO_EMAIL',
    route_to_leads: hasEmail,
    email_source: 'snov_reveal_verified',
    current_company_name: m.name || p.company_name, current_company_title: m.title || '',
    final_company_name: m.name || p.company_name, final_company_domain: p.company_domain,
    final_job_title: m.title || p.job_title,
    verification_reason: 'Still at ' + (m.name || p.company_name) + '; designation changed from "' + p.job_title + '" to "' + (m.title || '') + '"; email kept' } };
}

const target = positions.find((x) => HR_TITLE.test(x.title || '')) || positions[0];
const h = hostOf(target.url);
return { json: { ...out, employment_status: 'LEFT_COMPANY', lead_status: 'LEFT_COMPANY_RESEARCHING',
  email: '',
  old_email: p.email || '',
  current_company_name: target.name || '',
  current_company_domain: h && !h.includes('linkedin.com') ? h : '',
  current_company_title: target.title || '',
  verification_reason: 'No current LinkedIn position at ' + p.company_name + '; now ' + (target.title || 'role unknown') +
    ' at ' + (target.name || 'unknown') + '. Old email ' + (p.email || 'n/a') + ' discarded' } };

const HR_TITLE = /(\bhr\b|human resources|talent|recruit|people|hiring|staffing)/i;
const clean = (s) => String(s || '').toLowerCase()
  .replace(/&/g, ' and ')
  .replace(/\b(pvt|private|ltd|limited|llp|llc|inc|incorporated|corp|corporation|co|company)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim();
const hostOf = (u) => String(u || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
const sameDomain = (a, b) => !!a && !!b && (a === b || a.endsWith('.' + b) || b.endsWith('.' + a));
const sameName = (x, y) => {
  const a = clean(x), b = clean(y);
  if (!a || !b) return false;
  return a === b || (Math.min(a.length, b.length) >= 4 && (a.includes(b) || b.includes(a)));
};
const titleTokens = (t) => new Set(
  String(t || '').toLowerCase()
    .replace(/human resources?/g, 'hr')
    .replace(/recruitment|recruiter|recruiting/g, 'recruit')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(/\s+/)
    .filter((w) => w && !['and', 'of', 'the', 'for', 'a'].includes(w))
);
const titleMatch = (a, b) => {
  const x = titleTokens(a), y = titleTokens(b);
  if (!x.size || !y.size) return false;
  const [small, big] = x.size <= y.size ? [x, y] : [y, x];
  const inter = [...small].filter((w) => big.has(w)).length;
  if (small.size >= 2 && inter === small.size) return true;
  return inter / new Set([...x, ...y]).size >= 0.6;
};

const base = $('Evaluate Employment').item.json;
const r = $input.item.json || {};
const list = r.data && Array.isArray(r.data.prospects) ? r.data.prospects : [];
const first = String(base.first_name || '').toLowerCase();
const last = String(base.last_name || '').toLowerCase();
const liKey = (s) => String(s || '').toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/\/+$/, '');
const mine = liKey(base.linkedin_url);
const PREFIX = 'linkedin.com/in/';

let best = null, bestScore = 0;
for (const c of list) {
  const cf = String(c.first_name || '').toLowerCase();
  const cl = String(c.last_name || '').toLowerCase().replace(/\*+$/, '');
  if (!cf || cf !== first) continue;
  if (cl && last && !last.startsWith(cl)) continue;
  const co = c.company || {};
  const companyOk = sameName(co.name, base.current_company_name) ||
    sameDomain(String(co.domain || '').toLowerCase(), String(base.current_company_domain || '').toLowerCase());
  if (!companyOk) continue;
  const stem = liKey(c.linkedin_url).replace(/\*+$/, '');
  if (stem.length > PREFIX.length && mine && !mine.startsWith(stem)) continue;
  let score = 1;
  if (stem.length > PREFIX.length && mine.startsWith(stem)) score += 2;
  if (c.email_and_hidden_info_reveal) score += 1;
  if (score > bestScore) { best = c; bestScore = score; }
}

if (!best || !best.email_and_hidden_info_reveal) {
  return { json: { ...base, research_found: false } };
}
return { json: { ...base, research_found: true,
  reveal_url: best.email_and_hidden_info_reveal,
  research_title: best.job_title || '',
  research_company_domain: (best.company && best.company.domain) || '' } };

const base = $('Pick Re-Search Match').item.json;
const r = $input.item.json || {};
const d = r.data && !Array.isArray(r.data) ? r.data : {};
const emails = Array.isArray(d.emails) ? d.emails : [];
const best = emails.find((e) => e.smtp_status === 'valid') || emails[0];
const ok = r.status === 'completed' && !!best && !!best.email;
return { json: {
  ...base,
  first_name: d.first_name || base.first_name,
  last_name: d.last_name || base.last_name,
  linkedin_url: d.linkedin_url || base.linkedin_url,
  email: ok ? best.email : '',
  email_status: ok ? (best.smtp_status || 'unknown') : 'NOT_FOUND',
  email_source: 'snov_search_again_new_company',
  lead_status: ok ? 'APPROVED_REFOUND_NEW_COMPANY' : 'REVIEW_NO_EMAIL_AT_NEW_COMPANY',
  route_to_leads: ok,
  verification_reason: 'Left ' + base.company_name + '; LinkedIn shows ' + (base.current_company_title || 'role unknown') + ' at ' +
    base.current_company_name + '. Searched again at the new company and ' + (ok ? 'revealed a fresh email' : 'found no email') +
    '. Old email ' + (base.old_email || 'n/a') + ' discarded',
  final_company_name: base.current_company_name,
  final_company_domain: base.current_company_domain || base.research_company_domain || '',
  final_job_title: base.current_company_title || base.research_title || base.job_title,
} };

const base = $('Pick Re-Search Match').item.json;
const r = $input.item.json || {};
const row = Array.isArray(r.data) ? r.data[0] : null;
const domain = row && row.result && row.result.domain ? String(row.result.domain).toLowerCase() : '';
if (!domain) {
  return { json: { ...base, current_company_domain: '', lead_status: 'REVIEW_NEW_COMPANY_DOMAIN_NOT_FOUND',
    verification_reason: base.verification_reason + '. Domain for "' + base.current_company_name + '" could not be found' } };
}
return { json: { ...base, current_company_domain: domain } };

const base = $('Target Company Ready').item.json;
const r = $input.item.json || {};
const row = Array.isArray(r.data) ? r.data[0] : null;
const list = row && Array.isArray(row.result) ? row.result : [];
const best = list.find((e) => e.smtp_status === 'valid') || list[0];
const found = r.status === 'completed' && !!best && !!best.email;
const valid = found && best.smtp_status === 'valid';
const why = found && best.smtp_status !== 'valid' && best.unknown_status_reason ? ': ' + best.unknown_status_reason : '';
return { json: {
  ...base,
  email: found ? best.email : '',
  email_status: found ? best.smtp_status : 'NOT_FOUND',
  email_source: 'snov_email_finder_new_company',
  lead_status: valid ? 'APPROVED_REFOUND_NEW_COMPANY' : (found ? 'REVIEW_REFOUND_UNVERIFIED' : 'REVIEW_NO_EMAIL_AT_NEW_COMPANY'),
  route_to_leads: valid,
  verification_reason: 'Left ' + base.company_name + '; now ' + (base.current_company_title || 'role unknown') + ' at ' +
    base.current_company_name + ' (' + base.current_company_domain + '). Search again found no match, so used Email Finder: ' +
    (found ? best.smtp_status + why : 'no email found') + '. Old email ' + (base.old_email || 'n/a') + ' discarded',
  final_company_name: base.current_company_name,
  final_company_domain: base.current_company_domain,
  final_job_title: base.current_company_title || base.job_title,
} };
